pagoda.source:
const n = params.tiers;
const totalH = 12;
const baseH = 0.65;
const finialH = 1.45;
const storyH = (totalH - baseH - finialH) / n;
const roofH = storyH * 0.37;
const wallH = storyH * 0.60;
const stone = { preset: 'stone', color: '#77756f', roughness: 0.92, flatShading: true };
const stoneDark = { preset: 'stone', color: '#555650', roughness: 0.95 };
const wall = { preset: 'concrete', color: params.wallColor, roughness: 0.8 };
const timber = { preset: 'wood', color: '#6d241b', roughness: 0.72 };
const darkWood = { preset: 'wood', color: '#351b17', roughness: 0.78 };
const roof = { preset: 'brick', color: params.roofColor, roughness: 0.58, flatShading: true };
const roofEdge = { preset: 'metal', color: api.mix(params.roofColor, '#17241f', 0.38), metalness: 0.22, roughness: 0.5 };
const gold = { preset: 'gold', color: '#d6a62d', metalness: 0.72, roughness: 0.28 };
api.add(api.box(5.7, 0.28, 5.7).translate(0, 0.14, 0), stoneDark);
api.add(api.box(5.2, 0.37, 5.2).translate(0, 0.465, 0), stone);
for (let k = 0; k < 4; k++) {
  const a = k * Math.PI * 0.5;
  const x = Math.cos(a) * 2.72;
  const z = Math.sin(a) * 2.72;
  api.add(api.sphere(0.16, 1).scale(1, 0.55, 1).translate(x, 0.36, z), stoneDark);
}
let y = baseH;
let topWidth = 0;
for (let i = 0; i < n; i++) {
  const t = i / Math.max(1, n - 1);
  const wallW = 3.85 - t * 1.55;
  const deckW = wallW + 0.72;
  const roofW = wallW + 1.55;
  const wallY = y + wallH * 0.5;
  api.add(api.box(deckW, storyH * 0.09, deckW).translate(0, y + storyH * 0.045, 0), darkWood);
  api.add(api.box(wallW, wallH, wallW).translate(0, wallY, 0), wall);
  const post = Math.max(0.09, wallW * 0.035);
  for (let sx = -1; sx <= 1; sx += 2) {
    for (let sz = -1; sz <= 1; sz += 2) {
      api.add(api.box(post, wallH * 1.06, post).translate(sx * wallW * 0.48, wallY, sz * wallW * 0.48), timber);
    }
  }
  const beamY = y + wallH * 0.83;
  for (let q = 0; q < 4; q++) {
    api.add(api.box(wallW + post, post * 1.25, post * 0.9).translate(0, beamY, wallW * 0.505).rotate(0, q * 90, 0), timber);
    const faceZ = wallW * 0.507;
    for (let j = -2; j <= 2; j++) {
      const px = j * wallW * 0.145;
      api.add(api.box(post * 0.52, wallH * 0.48, post * 0.45).translate(px, y + wallH * 0.42, faceZ).rotate(0, q * 90, 0), darkWood);
    }
    api.add(api.box(wallW * 0.76, post * 0.48, post * 0.42).translate(0, y + wallH * 0.42, faceZ * 1.004).rotate(0, q * 90, 0), darkWood);
  }
  const railY = y + storyH * 0.25;
  if (i < n - 1) {
    for (let q = 0; q < 4; q++) {
      const rz = deckW * 0.46;
      api.add(api.box(deckW * 0.88, post * 0.38, post * 0.38).translate(0, railY, rz).rotate(0, q * 90, 0), darkWood);
      for (let j = -3; j <= 3; j++) {
        api.add(api.box(post * 0.3, storyH * 0.22, post * 0.3).translate(j * deckW * 0.115, y + storyH * 0.15, rz).rotate(0, q * 90, 0), darkWood);
      }
    }
  }
  const roofBaseY = y + wallH;
  const roofCenterY = roofBaseY + roofH * 0.42;
  api.add(api.cone(roofW * 0.71, roofH * 0.78, 4).rotate(0, 45, 0).translate(0, roofBaseY + roofH * 0.39, 0), roof);
  api.add(api.box(roofW, storyH * 0.055, roofW).translate(0, roofBaseY + storyH * 0.028, 0), roofEdge);
  const rise = roofH * 0.25;
  const thick = Math.max(0.08, storyH * 0.055);
  const fascia = [[-roofW * 0.5, 0], [roofW * 0.5, 0], [roofW * 0.57, rise], [roofW * 0.51, rise + thick], [-roofW * 0.51, rise + thick], [-roofW * 0.57, rise]];
  for (let q = 0; q < 4; q++) {
    api.add(api.extrude(fascia, thick).translate(0, roofBaseY, roofW * 0.47).rotate(0, q * 90, 0), roofEdge);
  }
  for (let q = 0; q < 4; q++) {
    const a = q * Math.PI * 0.5 + Math.PI * 0.25;
    api.add(api.sphere(thick * 0.72, 1).translate(Math.cos(a) * roofW * 0.74, roofBaseY + rise * 1.02, Math.sin(a) * roofW * 0.74), gold);
  }
  api.collider({ kind: 'box', halfExtents: [deckW * 0.5, storyH * 0.045, deckW * 0.5], offset: [0, y + storyH * 0.045, 0] });
  api.collider({ kind: 'box', halfExtents: [wallW * 0.5, wallH * 0.5, wallW * 0.5], offset: [0, wallY, 0] });
  y += storyH;
  topWidth = roofW;
}
const spireBase = totalH - finialH;
api.add(api.cylinder(topWidth * 0.15, topWidth * 0.19, finialH * 0.13, 12).translate(0, spireBase + finialH * 0.065, 0), gold);
api.add(api.sphere(finialH * 0.13, 2).scale(1, 0.7, 1).translate(0, spireBase + finialH * 0.22, 0), gold);
const mast = api.cylinder(finialH * 0.035, finialH * 0.055, finialH * 0.72, 10).translate(0, spireBase + finialH * 0.55, 0);
api.add(mast, gold);
for (let j = 0; j < 4; j++) {
  const rr = finialH * (0.19 - j * 0.025);
  api.add(api.torus(rr, finialH * 0.025).rotate(90, 0, 0).translate(0, spireBase + finialH * (0.38 + j * 0.12), 0), gold);
}
api.add(api.cone(finialH * 0.09, finialH * 0.28, 10).translate(0, totalH - finialH * 0.14, 0), gold);
api.collider({ kind: 'box', halfExtents: [2.85, 0.14, 2.85], offset: [0, 0.14, 0] });
api.collider({ kind: 'cylinder', radius: finialH * 0.06, halfHeight: finialH * 0.45, offset: [0, spireBase + finialH * 0.52, 0] });
return api.build();

hero-statue.source:
const S = params.height / 2.8;
const marble = { preset: 'stone', roughness: 0.35, metalness: 0.0, color: '#ffffff' };
const stoneM = { preset: 'stone', roughness: 0.9, flatShading: true, color: '#ffffff' };
const darkM = { preset: 'stone', color: '#2b2a29', roughness: 0.8 };
const lineM = { preset: 'stone', color: '#c9c3b4', roughness: 0.7 };
const vein = (m) => m.vertexColor((x, y, z) => {
  const n = Math.abs(api.noise3(x * 3.2, y * 2.4, z * 3.2));
  const n2 = Math.abs(api.noise3(x * 7 + 5, y * 5, z * 7));
  let t = 0;
  if (n < 0.09) t = params.veining; else if (n2 < 0.05) t = params.veining * 0.6;
  return api.mix(params.marbleColor, '#8a8c92', t);
});
const stoneCol = (m) => m.vertexColor((x, y, z) => api.mix(params.stoneColor, '#4d4b48', 0.4 * (0.5 + 0.5 * api.noise3(x * 4, y * 4, z * 4))));
const add = (m, isStone) => { m.scale(S); if (isStone) { stoneCol(m); api.add(m, stoneM); } else { vein(m); api.add(m, marble); } };
add(api.box(0.9, 0.2, 0.9).translate(0, 0.1, 0), true);
add(api.box(0.75, 0.15, 0.75).translate(0, 0.275, 0), true);
add(api.box(0.6, 0.5, 0.6).translate(0, 0.6, 0), true);
add(api.box(0.72, 0.1, 0.72).translate(0, 0.9, 0), true);
for (let s = 0; s < 4; s++) {
  const plate = api.box(0.4, 0.12, 0.014).translate(0, 0.6, 0.303).rotate(0, s * 90, 0).scale(S);
  api.add(plate, darkM);
  for (let l = 0; l < 3; l++) {
    const w = [0.32, 0.28, 0.22][l];
    api.add(api.box(w, 0.012, 0.012).translate(0, 0.635 - l * 0.035, 0.312).rotate(0, s * 90, 0).scale(S), lineM);
  }
}
const y0 = 0.95;
const P = [[0, 0], [0.30, 0], [0.31, 0.04], [0.27, 0.08], [0.285, 0.12], [0.255, 0.16], [0.27, 0.2], [0.24, 0.26], [0.255, 0.3], [0.225, 0.4], [0.24, 0.44], [0.21, 0.55], [0.225, 0.59], [0.195, 0.7], [0.21, 0.74], [0.185, 0.85], [0.2, 0.89], [0.19, 1.0], [0.21, 1.04], [0.2, 1.15], [0.23, 1.25], [0.23, 1.33], [0.17, 1.42], [0.07, 1.47], [0.05, 1.5], [0, 1.5]];
const robe = api.lathe(P.map(p => [p[0], p[1] + y0]), 28);
robe.displace((x, y, z) => 0.012 * Math.sin(Math.atan2(z, x) * 7 + y * 3));
add(robe, false);
add(api.sphere(0.2, 2).scale(1.25, 0.55, 0.8).translate(0, y0 + 1.33, 0), false);
// drape rings hugging the robe
for (let i = 0; i < 4; i++) {
  const yy = 0.18 + i * 0.22;
  const r = 0.27 - i * 0.022;
  add(api.torus(r, 0.03).rotate(90, 0, 0).scale(1, 1, 0.85).rotate(0, 0, (i % 2 ? 6 : -6)).translate(0, y0 + yy, 0), false);
}
// diagonal sash
add(api.tube([[-0.2, y0 + 1.3, 0.05], [-0.08, y0 + 1.1, 0.19], [0.05, y0 + 0.85, 0.2], [0.17, y0 + 0.6, 0.19]], 0.05, 10), false);
add(api.tube([[0.17, y0 + 0.6, 0.19], [0.2, y0 + 0.4, 0.2], [0.18, y0 + 0.2, 0.25]], 0.045, 8), false);
// feet
for (const sx of [-1, 1]) add(api.sphere(0.07, 2).scale(0.9, 0.5, 1.9).translate(sx * 0.1, y0 + 0.035, 0.29), false);
// left arm
add(api.sphere(0.07, 2).translate(-0.22, y0 + 1.3, 0), false);
add(api.tube([[-0.22, y0 + 1.3, 0], [-0.28, y0 + 1.1, 0.03], [-0.27, y0 + 0.88, 0.06]], 0.055, 10), false);
add(api.sphere(0.045, 2).translate(-0.27, y0 + 0.82, 0.07), false);
// right arm bent
add(api.sphere(0.07, 2).translate(0.22, y0 + 1.3, 0), false);
add(api.tube([[0.22, y0 + 1.3, 0], [0.31, y0 + 1.15, 0.06], [0.36, y0 + 1.1, 0.12]], 0.055, 10), false);
add(api.sphere(0.055, 2).translate(0.36, y0 + 1.1, 0.12), false);
add(api.tube([[0.36, y0 + 1.1, 0.12], [0.4, y0 + 1.35, 0.12], [0.4, y0 + 1.6, 0.1]], 0.05, 10), false);
add(api.sphere(0.05, 2).translate(0.4, y0 + 1.63, 0.1), false);
// wreath
const wc = [0.4, y0 + 1.76, 0.1];
const wr = api.torus(0.11, 0.018).rotate(0, 20, 0).translate(wc[0], wc[1], wc[2]);
wr.scale(S); wr.vertexColor(() => params.wreathColor); api.add(wr, marble);
for (let i = 0; i < 16; i++) {
  const a = i / 16 * Math.PI * 2;
  const lf = api.sphere(0.025, 1).scale(1, 0.5, 2).rotate(0, 0, a * 57.3 + 90).translate(Math.cos(a) * 0.11, Math.sin(a) * 0.11, 0).rotate(0, 20, 0).translate(wc[0], wc[1], wc[2]);
  lf.scale(S); lf.vertexColor(() => params.wreathColor); api.add(lf, marble);
}
// neck and head
add(api.cylinder(0.045, 0.055, 0.1, 10).translate(0, y0 + 1.52, 0), false);
const hc = y0 + 1.66;
const head = api.sphere(0.1, 3).scale(0.9, 1.1, 1).rotate(0, 0, params.tilt).translate(0, hc, 0);
add(head, false);
for (let i = 0; i < 30; i++) {
  const a = i * 2.4, k = i / 30;
  const el = 0.2 + k * 1.2;
  const hx = Math.cos(a) * Math.cos(el) * 0.1, hy = Math.sin(el) * 0.11, hz = Math.sin(a) * Math.cos(el) * 0.1;
  if (hz > 0.05 && hy < 0.07) continue;
  add(api.sphere(0.03, 1).translate(hx, hy, hz).rotate(0, 0, params.tilt).translate(0, hc, 0), false);
}
api.collider({ kind: 'box', halfExtents: [0.45 * S, 0.475 * S, 0.45 * S], offset: [0, 0.475 * S, 0] });
api.collider({ kind: 'cylinder', radius: 0.28 * S, halfHeight: 0.75 * S, offset: [0, 1.7 * S, 0] });
api.collider({ kind: 'box', halfExtents: [0.15 * S, 0.4 * S, 0.12 * S], offset: [0.35 * S, 2.45 * S, 0.1 * S] });
return api.build();
